import type { DiscoveryMetadata, Preset, PropDef, Status } from "./types";

export type ProductFamily = "media" | "forms" | "data" | "collections" | "overlays";
export type ProductRegistryEntry = {
  slug: string; name: string; family: ProductFamily; description: string; status: Status;
  tags: string[]; interactions: string[]; builtOn: string[]; importPath: string; usage: string;
  props: PropDef[]; presets: Preset[]; demoPath: string; skill: string;
  accessibility: string[]; reducedMotion: string; performance: string[];
  whenToUse: string[]; whenNotToUse: string[]; related: string[];
  discovery?: DiscoveryMetadata;
};

type Config = Omit<ProductRegistryEntry, "status" | "importPath" | "demoPath" | "skill" | "props" | "presets" | "accessibility" | "reducedMotion"> & {
  component: string; primaryProp: PropDef; quiet?: Record<string, number | string | boolean>;
  accessibility?: string[]; reducedMotion?: string;
};

const entry = ({ component, primaryProp, quiet = { disabled: true }, accessibility, reducedMotion, ...item }: Config): ProductRegistryEntry => ({
  ...item,
  status: "ready",
  importPath: `import { ${component} } from "@pinky-ui/systems";`,
  props: [primaryProp, ...(primaryProp.name === "className" ? [] : [{ name: "className", type: "string", description: "Styles the outer interaction surface." }])],
  presets: [{ name: "Default", description: "Restrained production behaviour.", props: {} }, { name: "Quiet", description: "Reduced intensity for dense product screens.", props: quiet }],
  demoPath: `/${item.family}#${item.slug}`,
  skill: item.slug,
  accessibility: accessibility ?? ["Keyboard and touch paths match the pointer interaction.", "Stable labels and values remain available without motion."],
  reducedMotion: reducedMotion ?? "Motion resolves immediately while semantics, focus and state remain unchanged.",
});

