export const productSystems = { media: mediaSystems, forms: formSystems, data: dataSystems, collections: collectionSystems, overlays: overlaySystems };
export const allProductSystems = [...mediaSystems, ...formSystems, ...dataSystems, ...collectionSystems, ...overlaySystems];
export const getProductSystem = (slug: string) => allProductSystems.find((item) => item.slug === slug);
export function filterProductSystems(family: ProductFamily | "all" = "all", query = "") {
  const needle = query.trim().toLowerCase();
  return allProductSystems.filter((item) => (family === "all" || item.family === family) && (!needle || [item.name, item.description, ...item.tags].join(" ").toLowerCase().includes(needle)));
}
